#ifndef CSM_CLI_H
#define CSM_CLI_H

#include <stdio.h>

#define CLI_MAX_OPTIONS 16

enum {
	EXIT_PARTIAL = 1,
	EXIT_USAGE = 2,
	EXIT_CLAUDE_RUNNING = 3
};

struct cli_option {
	char short_name;
	const char *long_name;
	int has_arg;
	int id;
};

enum cli_error_kind {
	CLI_OK,
	CLI_UNKNOWN,
	CLI_NEEDS_ARG,
	CLI_NO_ARG
};

struct cli_parsed {
	unsigned long flags;
	const char *args[CLI_MAX_OPTIONS];
	char **operands;
	int operand_count;
	enum cli_error_kind error;
	char *error_option;
};

int cli_parse(int argc, char **argv, const struct cli_option *options,
    struct cli_parsed *out);
void cli_free(struct cli_parsed *parsed);
int cli_confirm(FILE *in, FILE *out, const char *question);
int cli_run(int argc, char **argv);

#endif
